from django.db import migrations

# Five more badges (demo pack 2026-10-18), next to the starter set of 0021.
# These are the default thresholds — afterwards the Achievement row is the one
# place a threshold lives (editable in the Django admin); the rules per code are
# in myapp/services/achievements.py. Weekly regularity, never a daily streak.
NEW_BADGES = [
    # code, tier, category, threshold, sort_order
    ("tasks_5", "bronze", "milestone", 5, 15),        # 5 completed requests
    ("tasks_25", "silver", "milestone", 25, 25),      # 25 completed requests
    ("high_rating", "silver", "quality", 5, 55),      # >= 5 visible reviews, average >= 4.5
    ("regular", "silver", "steady", 4, 72),           # completed requests in 4 weeks in a row
    ("long_term", "silver", "steady", 60, 75),        # 60+ days on the platform + a completed request
]


# Badges a curator / admin gives by hand (services.achievements.MANUAL_CODES).
MANUAL_CODES = ["mentor"]


def add_badges(apps, schema_editor):
    Achievement = apps.get_model("myapp", "Achievement")
    Achievement.objects.filter(code__in=MANUAL_CODES).update(is_manual=True)
    for code, tier, category, threshold, order in NEW_BADGES:
        Achievement.objects.get_or_create(
            code=code,
            defaults={"tier": tier, "category": category, "threshold": threshold,
                      "sort_order": order, "is_active": True},
        )


def remove_badges(apps, schema_editor):
    apps.get_model("myapp", "Achievement").objects.filter(code__in=[row[0] for row in NEW_BADGES]).delete()


class Migration(migrations.Migration):

    dependencies = [
        ('myapp', '0032_achievement_is_manual'),
    ]

    operations = [
        migrations.RunPython(add_badges, remove_badges),
    ]
